package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** One warehouse document per parcel. RSL tasks are private stock-source ledgers, never sent to WMS. */
@Service public class SharedRefundDocuments {
    @Resource WmsStore db;
    @Resource WmsCarrierBridge carrierBridge;
    @Resource WmsConnections connections;
    @Resource QimenReturnProtocol protocol;
    @Resource WmsInteractionLog logs;
    Map<String,Object> bound(String c,long plan){List<Map<String,Object>> rows=db.jdbc.queryForList("SELECT p.* FROM wms_refund_parcel_member m JOIN wms_refund_parcel p ON p.company_code=m.company_code AND p.id=m.parcel_id WHERE m.company_code=? AND m.plan_id=? AND m.active=1 ORDER BY m.id DESC LIMIT 1",c,plan);return rows.isEmpty()?null:rows.get(0);}
    Map<String,Object> document(String c,long parcel){return db.one("SELECT * FROM wms_refund_parcel_document WHERE company_code=? AND parcel_id=? ORDER BY generation DESC LIMIT 1",c,parcel);}
    boolean owns(String c,String sn){return db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_document WHERE company_code=? AND return_sn=?",Long.class,c,sn)>0;}
    @SuppressWarnings("unchecked") private Map<String,Object> object(Object v){try{return v instanceof Map?(Map<String,Object>)v:db.json.readValue(text(v),Map.class);}catch(Exception e){throw new IllegalArgumentException("退回来源快照不完整，请重新核对");}}
    private List<Map<String,Object>> sources(String c,long parcel){return db.jdbc.queryForList("SELECT m.*,t.accepted_quantity,t.posted_quantity,t.return_sn source_sn FROM wms_refund_parcel_member m LEFT JOIN wms_refund_return t ON t.company_code=m.company_code AND t.id=m.task_id WHERE m.company_code=? AND m.parcel_id=? AND m.active=1 ORDER BY m.plan_id LIMIT 101",c,parcel);}
    Map<String,Object> prepare(String c,long plan,Map<String,Object> authorization,RefundReturnService returns){Map<String,Object> p=bound(c,plan);require(p!=null,"请先关联退回包裹");long parcel=id(p.get("id"));
        db.tx().execute(tx->{Map<String,Object> locked=db.one("SELECT * FROM wms_refund_parcel WHERE company_code=? AND id=? FOR UPDATE",c,parcel);require(id(authorization.get("parcel_version"))==id(locked.get("control_version")),"共同THK范围变化，请刷新后确认");List<Map<String,Object>> old=db.jdbc.queryForList("SELECT * FROM wms_refund_parcel_document WHERE company_code=? AND parcel_id=? ORDER BY generation DESC LIMIT 1 FOR UPDATE",c,parcel);if(!old.isEmpty()&&!"CONFIRMED".equals(old.get(0).get("cancel_state")))return null;
            List<Map<String,Object>> ms=sources(c,parcel);require(!ms.isEmpty()&&ms.size()<=100,"包裹来源数量无效");List<Map<String,Object>> lines=new ArrayList<>();long total=0;
            for(Map<String,Object> m:ms){if(m.get("task_id")!=null&&id(m.get("quantity"))==id(m.get("accepted_quantity")))continue;Map<String,Object> input=object(m.get("request_json"));require(id(input.get("quantity"))==id(m.get("quantity"))&&text(input.get("sku_sn")).equals(text(m.get("sku_sn")))&&id(input.get("refund_id"))==id(m.get("refund_id")),"包裹来源快照与计划不一致");Map<String,Object> task=returns.stageSource(c,id(m.get("plan_id")),input);require(text(task.get("return_sn")).startsWith("RSL"),"来源已存在独立仓库安排，请先核对原单");require("NONE".equals(task.get("cancel_state")),"已截停的来源必须通过重排剩余退回生成新安排，不能直接再次下发");lines.add(map("line_no",text(m.get("id")),"task_id",task.get("id"),"plan_id",m.get("plan_id"),"refund_id",m.get("refund_id"),"refund_sn",m.get("refund_sn"),"sku_sn",m.get("sku_sn"),"goods_name",input.getOrDefault("goods_name",m.get("sku_sn")),"quantity",m.get("quantity"),"platform_tid",m.get("platform_tid")));total=Math.addExact(total,id(m.get("quantity")));}
            require(!lines.isEmpty(),"包裹没有剩余待收来源");String sn="THK"+UUID.randomUUID().toString().replace("-","");long doc=db.insert("wms_refund_parcel_document",map("company_code",c,"parcel_id",parcel,"generation",old.isEmpty()?1:id(old.get(0).get("generation"))+1,"return_sn",sn,"quantity",total,"payload",db.encode(lines)));
            long ticket=db.insert("wms_tickets",map("company_code",c,"sn",sn,"business_type","REFUND_IN","ticket_type",1,"original_sn",p.get("parcel_sn"),"root_order_sn",ms.get(0).get("order_sn"),"relation_sn",sn,"wms_simulation_code",p.get("store_code"),"wms_simulation_name",p.get("store_code"),"real_store_code",p.get("real_store_code"),"actual_warehouse",1,"status_ticket",1,"user_name","退款合包处理","remark","合包共同退货入库单；退款归属按明细保留"));
            for(Map<String,Object> line:lines){Map<String,Object> source=db.one("SELECT * FROM wms_refund_return WHERE company_code=? AND id=?",c,line.get("task_id"));db.insert("wms_tickets_goods",map("company_code",c,"sn",sn,"source_line_id",line.get("task_id"),"inventory_type","ZP","sku_sn",line.get("sku_sn"),"goods_name",line.getOrDefault("goods_name",line.get("sku_sn")),"batch_code","","number_expected",line.get("quantity"),"number_actually",0,"number_dif_actually",line.get("quantity"),"purchase_price",source.get("unit_cost"),"inventory_is_handle",0));}
            db.jdbc.update("UPDATE wms_refund_parcel_document SET ticket_id=? WHERE company_code=? AND id=?",ticket,c,doc);db.jdbc.update("UPDATE wms_refund_parcel SET control_version=control_version+1 WHERE company_code=? AND id=?",c,parcel);return null;
        });send(c,parcel,"CREATE");return decorate(c,plan,returns.sourceDetail(c,plan));
    }
    Map<String,Object> decorate(String c,long plan,Map<String,Object> result){Map<String,Object> p=bound(c,plan);if(p==null)return result;List<Map<String,Object>> ds=db.jdbc.queryForList("SELECT * FROM wms_refund_parcel_document WHERE company_code=? AND parcel_id=? ORDER BY generation DESC LIMIT 1",c,p.get("id"));if(ds.isEmpty())return result;Map<String,Object> d=ds.get(0);result.put("shared_document",true);result.put("parcel_id",p.get("id"));result.put("parcel_sn",p.get("parcel_sn"));result.put("return_sn",d.get("return_sn"));result.put("ticket_id",d.get("ticket_id"));result.put("dispatch_state",d.get("dispatch_state"));result.put("attempts",d.get("attempts"));result.put("cancel_state",d.get("cancel_state"));result.put("external_order",d.get("external_order"));result.put("last_error",d.get("last_error"));result.put("warehouse_status",d.get("warehouse_status"));result.put("warehouse_quantity",d.get("quantity"));result.put("parcel_version",p.get("control_version"));result.put("warehouse_document",publicDocument(d));
        List<Map<String,Object>> aliases=db.jdbc.queryForList("SELECT t.id source_id,t.return_sn source_sn,d.* FROM wms_refund_return t JOIN wms_tickets_goods g ON UPPER(g.company_code)=t.company_code AND g.source_line_id=t.id JOIN wms_refund_parcel_document d ON d.company_code=t.company_code AND d.return_sn=g.sn WHERE t.company_code=? AND t.plan_id=?",c,plan);for(Map<String,Object> row:list(result.get("documents"))){Map<String,Object> own=aliases.stream().filter(x->id(x.get("source_id"))==id(row.get("id"))).findFirst().orElse(d);row.put("return_sn",own.get("return_sn"));row.put("ticket_id",own.get("ticket_id"));row.put("shared_document",true);row.put("dispatch_state",own.get("dispatch_state"));row.put("attempts",own.get("attempts"));row.put("cancel_state",own.get("cancel_state"));row.put("control_version",own.get("control_version"));row.put("external_order",own.get("external_order"));}
        for(String key:Arrays.asList("lines","reviews"))for(Map<String,Object> row:list(result.get(key))){Map<String,Object> own=aliases.stream().filter(x->text(x.get("source_sn")).equals(text(row.get("return_sn")))).findFirst().orElse(d);row.put("return_sn",own.get("return_sn"));}return result;
    }
    @SuppressWarnings("unchecked") private List<Map<String,Object>> list(Object v){return v instanceof List?(List<Map<String,Object>>)v:Collections.emptyList();}
    Map<String,Object> publicDocument(Map<String,Object> raw){Map<String,Object> d=new LinkedHashMap<>(raw);d.remove("lease_token");d.remove("lease_until");d.remove("payload");return d;}
    Map<String,Object> action(String c,long plan,String action,Map<String,Object> input,RefundReturnService returns){Map<String,Object> p=bound(c,plan);require(p!=null,"退回包裹不存在");long parcel=id(p.get("id"));
        if("rebuild".equals(action)){rebuild(c,parcel,input,returns);return prepare(c,plan,map("parcel_version",db.one("SELECT control_version FROM wms_refund_parcel WHERE company_code=? AND id=?",c,parcel).get("control_version")),returns);}
        if("posting".equals(action)){for(Map<String,Object> m:sources(c,parcel))returns.postAssigned(c,id(m.get("plan_id")));}
        else if("cancel".equals(action)){db.tx().execute(tx->{Map<String,Object> locked=db.one("SELECT * FROM wms_refund_parcel WHERE company_code=? AND id=? FOR UPDATE",c,parcel);Map<String,Object> d=db.one("SELECT * FROM wms_refund_parcel_document WHERE company_code=? AND parcel_id=? ORDER BY generation DESC LIMIT 1 FOR UPDATE",c,parcel);require(Boolean.TRUE.equals(input.get("confirmed_shared"))&&id(input.get("parcel_version"))==id(locked.get("control_version")),"这是共同THK；请在退回包裹中核对全部关联退款并确认整单截停");require(d.get("lease_until")==null||!((java.sql.Timestamp)d.get("lease_until")).toLocalDateTime().isAfter(java.time.LocalDateTime.now()),"共同THK正在交互，请稍后重试");String why=required(input,"reason",500);required(input,"evidence",1000);require(!"CONFIRMED".equals(d.get("cancel_state")),"共同THK已截停");db.jdbc.update("UPDATE wms_refund_parcel_document SET cancel_state='PENDING',last_error=?,control_version=control_version+1 WHERE company_code=? AND id=?",why,c,d.get("id"));return null;});send(c,parcel,"CANCEL");}
        else if(Arrays.asList("query","dispatch","retry").contains(action)){if("retry".equals(action))db.tx().execute(tx->{Map<String,Object> d=db.one("SELECT * FROM wms_refund_parcel_document WHERE company_code=? AND parcel_id=? ORDER BY generation DESC LIMIT 1 FOR UPDATE",c,parcel);require("FAILED".equals(d.get("dispatch_state"))&&"NONE".equals(d.get("cancel_state")),"仅明确失败可重试；结果不明请查询原THK");db.jdbc.update("UPDATE wms_refund_parcel_document SET dispatch_state='PENDING' WHERE company_code=? AND id=?",c,d.get("id"));return null;});send(c,parcel,"query".equals(action)?"QUERY":"CREATE");}
        else throw new IllegalArgumentException("共同THK请在退回包裹中处理；重排或单张退款撤回须先确认整单截停和其他退款影响");
        syncTicket(c,parcel);return decorate(c,plan,returns.sourceDetail(c,plan));
    }
    private void rebuild(String c,long parcel,Map<String,Object> input,RefundReturnService returns){db.tx().execute(tx->{Map<String,Object> p=db.one("SELECT * FROM wms_refund_parcel WHERE company_code=? AND id=? FOR UPDATE",c,parcel);Map<String,Object> d=document(c,parcel);require(Boolean.TRUE.equals(input.get("confirmed_shared"))&&id(input.get("parcel_version"))==id(p.get("control_version"))&&"CONFIRMED".equals(d.get("cancel_state")),"请确认共同THK已整单截停并核对全部剩余来源");require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_receipt WHERE company_code=? AND parcel_id=? AND state='WAIT_ALLOCATION'",Long.class,c,parcel)==0,"请先处理全部待核对回传，再重排剩余退回");required(input,"reason",500);required(input,"evidence",1000);int count=0;for(Map<String,Object> m:sources(c,parcel)){long left=id(m.get("quantity"))-id(m.get("accepted_quantity"));if(left==0)continue;Map<String,Object> command=new LinkedHashMap<>(object(m.get("request_json")));command.put("quantity",left);Map<String,Object> task=returns.stageNextSource(c,id(m.get("plan_id")),command);db.jdbc.update("UPDATE wms_refund_parcel_member SET active=0 WHERE company_code=? AND id=?",c,m.get("id"));Map<String,Object> next=new LinkedHashMap<>(m);for(String key:Arrays.asList("id","create_time","accepted_quantity","posted_quantity","source_sn"))next.remove(key);next.put("generation",task.get("generation"));next.put("task_id",task.get("id"));next.put("quantity",left);next.put("request_json",db.encode(command));next.put("active",1);db.insert("wms_refund_parcel_member",next);count++;}require(count>0,"共同THK没有剩余待收数量");db.jdbc.update("UPDATE wms_refund_parcel SET control_version=control_version+1 WHERE company_code=? AND id=?",c,parcel);return null;});}
    @SuppressWarnings("unchecked") private void send(String c,long parcel,String action){String lease=UUID.randomUUID().toString().replace("-","");long doc=id(document(c,parcel).get("id"));boolean claimed=db.tx().execute(tx->{db.one("SELECT id FROM wms_refund_parcel WHERE company_code=? AND id=? FOR UPDATE",c,parcel);Map<String,Object> d=db.one("SELECT * FROM wms_refund_parcel_document WHERE company_code=? AND id=? FOR UPDATE",c,doc);if("CREATE".equals(action)&&"ACCEPTED".equals(d.get("dispatch_state")))return false;require(!"CREATE".equals(action)||("PENDING".equals(d.get("dispatch_state"))&&"NONE".equals(d.get("cancel_state"))),"共同THK已有下发或截单，请查询原单");return db.jdbc.update("UPDATE wms_refund_parcel_document SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND),attempts=attempts+IF(?='CREATE',1,0),dispatch_state=IF(?='CREATE','SENDING',dispatch_state) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,action,action,c,doc)==1;});if(!claimed)return;
        long log=0,start=System.currentTimeMillis();boolean contacted=false;String secret="";
        try{Map<String,Object> p=db.one("SELECT * FROM wms_refund_parcel WHERE company_code=? AND id=?",c,parcel),d=document(c,parcel);Map<String,Object> connection="CREATE".equals(action)?connections.usable(c,id(p.get("connection_id"))):connections.get(c,id(p.get("connection_id")));Map<String,Object> wire=new LinkedHashMap<>(p);wire.putAll(d);wire.put("business_type","REFUND_IN");wire.put("business_sn",p.get("parcel_sn"));wire.put("return_carrier",p.get("carrier_code"));wire.put("return_waybill",p.get("waybill"));wire.put("cancel_reason",d.get("last_error"));wire.put("order_lines",db.json.readValue(text(d.get("payload")),List.class));if("CREATE".equals(action)){Map<String,Object> carrier=carrierBridge.inbound(c,wire,connection);wire.put("return_carrier",carrier.get("external_code"));}secret=connections.secret(connection);WmsProtocol.Wire request=protocol.request(connection,secret,action,wire);log=logs.start(c,id(connection.get("id")),null,text(d.get("return_sn")),"OUT","REFUND_RETURN_"+action,request.body);contacted=true;String response=WmsHttp.post(request);WmsProtocol.Reply reply=protocol.reply(action,response);require(reply.documentSn.isEmpty()||reply.documentSn.equals(text(d.get("return_sn"))),"仓库返回共同THK不一致");require(reply.externalOrder.isEmpty()||text(d.get("external_order")).isEmpty()||reply.externalOrder.equals(text(d.get("external_order"))),"仓库单号与原受理不一致");require(reply.owner.isEmpty()||reply.owner.equals(text(p.get("external_owner"))),"仓库货主不一致");require(reply.warehouse.isEmpty()||reply.warehouse.equals(text(p.get("external_warehouse"))),"仓库编码不一致");
            if(!"CANCEL".equals(action)&&reply.success){require(!reply.externalOrder.isEmpty(),"仓库缺少受理单号，请查询原单");if("QUERY".equals(action))require(reply.documentSn.equals(text(d.get("return_sn")))&&!reply.owner.isEmpty()&&!reply.warehouse.isEmpty(),"仓库查询身份不完整");}
            final long logId=log;db.tx().execute(tx->{db.one("SELECT id FROM wms_refund_parcel WHERE company_code=? AND id=? FOR UPDATE",c,parcel);require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_refund_parcel_document WHERE company_code=? AND id=? AND lease_token=? AND lease_until>NOW()",Long.class,c,doc,lease)==1,"共同THK交互租约失效");
                if("CANCEL".equals(action)||("QUERY".equals(action)&&reply.success&&"CANCELED".equals(reply.status)&&!"NONE".equals(d.get("cancel_state")))){db.jdbc.update("UPDATE wms_refund_parcel_document SET cancel_state=?,dispatch_state=IF(?=1,'CANCELED',dispatch_state),last_error=?,control_version=control_version+1 WHERE company_code=? AND id=?",reply.success?"CONFIRMED":"REJECTED",reply.success?1:0,reply.success?"":"仓库拒绝整单截停",c,doc);if(reply.success)db.jdbc.update("UPDATE wms_refund_return t JOIN wms_refund_parcel_member m ON m.company_code=t.company_code AND m.task_id=t.id SET t.cancel_state='CONFIRMED',t.dispatch_state='CANCELED',t.cancelled_quantity=GREATEST(t.quantity-t.accepted_quantity,0),t.control_version=t.control_version+1 WHERE m.company_code=? AND m.parcel_id=?",c,parcel);}
                else{db.jdbc.update("UPDATE wms_refund_parcel_document SET dispatch_state=?,external_order=IF(?='',external_order,?),warehouse_status=?,last_error=?,control_version=control_version+1 WHERE company_code=? AND id=?",reply.success?"ACCEPTED":("CREATE".equals(action)?"FAILED":text(d.get("dispatch_state"))),reply.externalOrder,reply.externalOrder,reply.status,reply.success?"":"仓库明确拒绝请求",c,doc);if(reply.success)db.jdbc.update("UPDATE wms_refund_return t JOIN wms_refund_parcel_member m ON m.company_code=t.company_code AND m.task_id=t.id SET t.dispatch_state=IF(t.cancel_state='CONFIRMED','CANCELED','ACCEPTED'),t.external_order=?,t.warehouse_status=?,t.attempts=GREATEST(t.attempts,1) WHERE m.company_code=? AND m.parcel_id=?",reply.externalOrder,reply.status,c,parcel);}
                db.jdbc.update("UPDATE wms_refund_parcel SET control_version=control_version+1 WHERE company_code=? AND id=?",c,parcel);dirty(c,parcel);logs.finish(logId,reply.success?"SUCCESS":"FAILED",response,reply.success?"":"仓库拒绝请求",System.currentTimeMillis()-start);logs.describe(logId,"共同THK "+d.get("return_sn")+"；关联退款 "+sources(c,parcel).stream().map(m->text(m.get("refund_sn"))).reduce((a,b)->a+","+b).orElse(""));return null;});
        }catch(Exception failure){String why=failure instanceof IllegalArgumentException?text(failure.getMessage()):"共同THK交互未完成，请查询原单";if(!secret.isEmpty())why=why.replace(secret,"***");db.jdbc.update("UPDATE wms_refund_parcel_document SET dispatch_state=IF(?='CREATE',?,dispatch_state),cancel_state=IF(?='CANCEL','UNKNOWN',cancel_state),last_error=? WHERE company_code=? AND id=? AND lease_token=?",action,contacted?"UNKNOWN":"FAILED",action,why,c,doc,lease);if(log>0)logs.finish(log,"UNKNOWN","",why,System.currentTimeMillis()-start);
        }finally{db.jdbc.update("UPDATE wms_refund_parcel_document SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",c,doc,lease);syncTicket(c,parcel);}
    }
    void dirty(String c,long parcel){db.jdbc.update("UPDATE wms_refund_return t JOIN wms_refund_parcel_member m ON m.company_code=t.company_code AND m.task_id=t.id SET t.progress_revision=t.progress_revision+1,t.notify_pending=1 WHERE m.company_code=? AND m.parcel_id=?",c,parcel);}
    @SuppressWarnings("unchecked") void syncTicket(String c,long parcel){for(Map<String,Object> d:db.jdbc.queryForList("SELECT * FROM wms_refund_parcel_document WHERE company_code=? AND parcel_id=?",c,parcel)){db.jdbc.update("UPDATE wms_tickets_goods g JOIN wms_refund_return t ON UPPER(g.company_code)=t.company_code AND g.source_line_id=t.id SET g.number_actually=t.posted_quantity,g.number_dif_actually=GREATEST(g.number_expected-t.posted_quantity,0),g.cancelled_quantity=IF(t.cancel_state='CONFIRMED',GREATEST(g.number_expected-t.accepted_quantity,0),0),g.inventory_is_handle=IF(t.posted_quantity>0,2,0),g.number_zp=(SELECT COALESCE(SUM(l.good_qty),0) FROM wms_refund_return_line l WHERE l.company_code=t.company_code AND l.task_id=t.id AND l.posted=1),g.number_cp=(SELECT COALESCE(SUM(l.bad_qty),0) FROM wms_refund_return_line l WHERE l.company_code=t.company_code AND l.task_id=t.id AND l.posted=1) WHERE UPPER(g.company_code)=? AND g.sn=?",c,d.get("return_sn"));long posted=db.jdbc.queryForObject("SELECT COALESCE(SUM(number_actually),0) FROM wms_tickets_goods WHERE UPPER(company_code)=? AND sn=?",Long.class,c,d.get("return_sn"));db.jdbc.update("UPDATE wms_tickets SET status_ticket=?,status_notify=?,inventory_status=?,cutoff_state=? WHERE UPPER(company_code)=? AND id=?","CONFIRMED".equals(d.get("cancel_state"))?(posted>0?2:5):posted==id(d.get("quantity"))?2:1,"ACCEPTED".equals(d.get("dispatch_state"))?1:0,posted>0?2:0,"CONFIRMED".equals(d.get("cancel_state"))?"COMPLETED":"NONE",c,d.get("ticket_id"));}}
}
